import { useMemo, useState } from 'react';
import { useIntl } from 'react-intl';

import { BasicContainer, DataStateHandler, Toggle } from 'components';
import { TableDataType } from 'components/Table/types';
import { Paragraph } from 'components/UI';

import { KpiDrillDownTable } from '../../../KpiDrillDownTable/KpiDrillDownTable';
import { TABLE_CONFIGS_SOURCESTATUS } from '../../config/tableConfig';
import { useRefreshStatus } from '../../hooks/useRefreshStatus/useRefreshStatus';
import { StyledRefreshStatusTable } from './RefreshStatus.styles';

interface RefreshStatusProps {
  data: TableDataType;
  loading?: boolean;
  error?: Error | null;
  empty?: boolean;
}

export const RefreshStatus: React.FC<RefreshStatusProps> = ({
  data,
  loading = false,
  error = null,
  empty = false,
}) => {
  const { formatMessage } = useIntl();
  const [showOnlyLE, setShowOnlyLE] = useState(false);
  const { filteredData } = useRefreshStatus({ showOnlyLE, data });
  const pageTitle = useMemo(
    () =>
      formatMessage({
        id: 'ValueCreation.PerformanceTool.market_share_official.sourceStatus.title',
      }),
    [formatMessage],
  );
  return (
    <BasicContainer
      header={{
        title: pageTitle,
        titleSize: 'H4',
        rightContent: (
          <>
            <Toggle
              checked={showOnlyLE}
              onCheckedChange={setShowOnlyLE}
              ariaLabel="Show only LE"
              ariaLabelledBy="show-only-le"
            />
            <Paragraph>Show only LE</Paragraph>
          </>
        ),
      }}
      layout={{
        headerPadding: 'mediumCompact',
        border: 'small',
        borderRadius: 'large',
        shadow: 'small',
        bodyPadding: false,
        bottomSeparator: 'border',
      }}
      fullWidth
    >
      <DataStateHandler
        loading={loading}
        error={error}
        empty={empty}
        message={{
          description: formatMessage({
            id: 'Common.dataUnavailable.title',
            defaultMessage: 'Data not available',
          }),
        }}
        skeletonProps={{
          height: '328px',
          width: '100%',
          length: 1,
          borderRadius: 'none',
        }}
      >
        <KpiDrillDownTable
          data={filteredData}
          config={TABLE_CONFIGS_SOURCESTATUS}
          tableStyle={StyledRefreshStatusTable}
        />
      </DataStateHandler>
    </BasicContainer>
  );
};
